//! "About Plassi": version, copyright, privacy and the licences of the
//! app and the third-party software and fonts built into it.

use std::sync::OnceLock;

use eframe::egui::{self, RichText};

use super::theme::{self, Palette};
use crate::i18n::tr;

/// Generated by scripts/notices.sh.
const NOTICES: &str = include_str!("../../THIRD_PARTY_NOTICES.md");

#[cfg(target_arch = "wasm32")]
const PRIVACY: &str =
    "Stored only in this browser on this device. No accounts, tracking or cookies.";
#[cfg(not(target_arch = "wasm32"))]
const PRIVACY: &str = "Stored only in files on this computer. No accounts or tracking.";

/// One `## ` part of the notices file.
struct Section {
    title: String,
    body: Vec<Block>,
}

enum Block {
    Heading(String),
    Text(String),
    Code(String),
}

fn sections() -> &'static [Section] {
    static PARSED: OnceLock<Vec<Section>> = OnceLock::new();
    PARSED.get_or_init(|| {
        let mut sections = vec![Section {
            title: "Plassi (AGPL-3.0-or-later)".to_owned(),
            body: vec![Block::Code(include_str!("../../LICENSE").to_owned())],
        }];
        sections.extend(parse(NOTICES));
        sections
    })
}

/// Splits the Markdown into sections of headings, paragraphs and code blocks.
/// Text before the first `## ` heading is skipped (it repeats the copyright).
fn parse(markdown: &str) -> Vec<Section> {
    let mut out: Vec<Section> = Vec::new();
    let mut code: Option<String> = None;
    for line in markdown.lines() {
        if let Some(buf) = code.as_mut() {
            if line.starts_with("```") {
                let text = code.take().unwrap_or_default();
                if let Some(s) = out.last_mut() {
                    s.body.push(Block::Code(text));
                }
            } else {
                buf.push_str(line);
                buf.push('\n');
            }
        } else if line.starts_with("```") {
            code = Some(String::new());
        } else if let Some(title) = line.strip_prefix("## ") {
            out.push(Section {
                title: title.to_owned(),
                body: Vec::new(),
            });
        } else if let Some(s) = out.last_mut() {
            let trimmed = line.trim_start_matches('#');
            if trimmed.len() != line.len() {
                s.body.push(Block::Heading(trimmed.trim().to_owned()));
            } else if !line.trim().is_empty() {
                s.body.push(Block::Text(line.to_owned()));
            }
        }
    }
    out
}

/// The (i) button that opens the About window.
pub(super) fn button(ui: &mut egui::Ui, p: Palette) {
    let id = egui::Id::new("about-plassi");
    let mut open = ui.ctx().data(|d| d.get_temp::<bool>(id)).unwrap_or(false);
    let response = theme::icon_button(ui, p, theme::Icon::Info, tr("About Plassi"), open);
    response.widget_info(|| {
        egui::WidgetInfo::labeled(egui::WidgetType::Button, true, tr("About Plassi"))
    });
    if response.clicked() {
        open = !open;
    }
    ui.ctx().data_mut(|d| d.insert_temp(id, open));
}

/// Draw independently of navigation, including when its menu is closed.
pub(super) fn show(ctx: &egui::Context, p: Palette) {
    let id = egui::Id::new("about-plassi");
    let mut open = ctx.data(|d| d.get_temp::<bool>(id)).unwrap_or(false);
    if open {
        window(ctx, p, &mut open);
    }
    ctx.data_mut(|d| d.insert_temp(id, open));
}

fn window(ctx: &egui::Context, p: Palette, open: &mut bool) {
    let viewport = ctx.content_rect().size();
    let width = (viewport.x - 80.0).clamp(200.0, 900.0);
    let height = (viewport.y - 80.0).max(200.0);
    egui::Window::new(tr("About Plassi"))
        .title_bar(false)
        .collapsible(false)
        .resizable(false)
        .fixed_size(egui::vec2(width, height))
        .frame(theme::card(p))
        .anchor(egui::Align2::CENTER_CENTER, egui::Vec2::ZERO)
        .show(ctx, |ui| {
            ui.set_width(width);
            let header_width = ui.available_width();
            ui.horizontal(|ui| {
                ui.add_space(theme::CONTROL_HEIGHT);
                ui.allocate_ui_with_layout(
                    egui::vec2(
                        (header_width
                            - 2.0 * theme::CONTROL_HEIGHT
                            - 2.0 * ui.spacing().item_spacing.x)
                            .max(0.0),
                        theme::CONTROL_HEIGHT,
                    ),
                    egui::Layout::centered_and_justified(egui::Direction::LeftToRight),
                    |ui| {
                        ui.label(
                            RichText::new(tr("About Plassi"))
                                .size(theme::text::BODY)
                                .strong(),
                        );
                    },
                );
                let response =
                    theme::icon_button(ui, p, theme::Icon::Close, tr("Close about window"), false);
                response.widget_info(|| {
                    egui::WidgetInfo::labeled(
                        egui::WidgetType::Button,
                        true,
                        tr("Close about window"),
                    )
                });
                if response.clicked() {
                    *open = false;
                }
            });
            ui.separator();
            egui::ScrollArea::vertical()
                .id_salt("about-content")
                .max_height((height - theme::CONTROL_HEIGHT - 60.0).max(80.0))
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    ui.label(
                        RichText::new(format!("Plassi {}", env!("CARGO_PKG_VERSION")))
                            .size(theme::text::TITLE)
                            .strong(),
                    );
                    ui.label(tr("© 2026 Niklas Iivari and contributors"));
                    ui.add(
                        egui::Label::new(tr("Free software under AGPL-3.0-or-later. No warranty."))
                            .wrap(),
                    );
                    ui.hyperlink_to(tr("Source code"), env!("CARGO_PKG_REPOSITORY"));
                    ui.add_space(theme::space::M);
                    theme::section_title(ui, p, tr("Privacy"));
                    ui.add(egui::Label::new(tr(PRIVACY)).wrap());
                    ui.add_space(theme::space::M);
                    theme::section_title(ui, p, tr("Licences"));
                    theme::hint(ui, p, tr("Software and fonts"));
                    ui.add_space(theme::space::S);
                    for section in sections() {
                        let width = (ui.available_width()
                            - ui.spacing().indent
                            - ui.spacing().button_padding.x)
                            .max(0.0);
                        let title = egui::WidgetText::from(crate::i18n::tr_any(&section.title))
                            .into_galley(
                                ui,
                                Some(egui::TextWrapMode::Wrap),
                                width,
                                egui::TextStyle::Button,
                            );
                        egui::CollapsingHeader::new(title)
                            .id_salt(&section.title)
                            .show(ui, |ui| section_body(ui, section));
                    }
                });
        });
}

fn section_body(ui: &mut egui::Ui, section: &Section) {
    for block in &section.body {
        match block {
            Block::Heading(text) => {
                ui.add_space(theme::space::S);
                ui.label(RichText::new(text).strong());
            }
            Block::Text(text) => {
                ui.add(egui::Label::new(RichText::new(text).size(theme::text::BODY)).wrap());
            }
            Block::Code(text) => {
                ui.add(
                    egui::Label::new(RichText::new(text).monospace().size(theme::text::BODY))
                        .wrap(),
                );
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn notices_cover_key_crates_and_fonts() {
        assert!(NOTICES.len() > 10_000);
        for name in [
            "egui",
            "eframe",
            "typst",
            "serde",
            "hypher",
            "epaint_default_fonts",
        ] {
            assert!(
                NOTICES.contains(&format!("{name} ")),
                "{name} missing from THIRD_PARTY_NOTICES.md"
            );
        }
        assert!(NOTICES.contains("Source Sans 3"));
        let titles: Vec<&str> = sections().iter().map(|s| s.title.as_str()).collect();
        assert!(titles.contains(&"Fonts"), "{titles:?}");
        assert!(titles.iter().any(|t| t.starts_with("Apache License")));
    }

    /// Every third-party package in Cargo.lock that is a normal dependency of
    /// the app is listed (by name). Run scripts/notices.sh after changing
    /// dependencies. Dev-only crates are allowed to be missing, so this only
    /// checks crates that egui, typst or eframe pull in.
    #[test]
    fn notices_match_cargo_lock_for_core_crates() {
        let lock = include_str!("../../Cargo.lock");
        let names: Vec<&str> = lock
            .lines()
            .filter_map(|l| l.strip_prefix("name = \""))
            .filter_map(|l| l.strip_suffix('"'))
            .filter(|n| {
                n.starts_with("egui")
                    || n.starts_with("epaint")
                    || n.starts_with("typst")
                    || *n == "eframe"
            })
            .filter(|n| !matches!(*n, "egui_kittest" | "egui-wgpu"))
            .collect();
        assert!(!names.is_empty());
        for name in names {
            assert!(
                NOTICES.contains(&format!("{name} ")),
                "{name} is in Cargo.lock but not in THIRD_PARTY_NOTICES.md"
            );
        }
    }

    #[test]
    fn parse_splits_sections_and_code() {
        let s = parse("# Top\nintro\n## A\n### Sub\nx 1\n```text\nline\n```\n## B\n");
        assert_eq!(s.len(), 2);
        assert_eq!(s[0].title, "A");
        assert!(matches!(&s[0].body[0], Block::Heading(h) if h == "Sub"));
        assert!(matches!(&s[0].body[2], Block::Code(c) if c == "line\n"));
    }
}
